DROP TABLE IF EXISTS `climate`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `climate` (
  `record_date` date NOT NULL,
  `location_id` int NOT NULL,
  `temperature_min_celsius` float DEFAULT NULL,
  `temperature_max_celsius` float DEFAULT NULL,
  `rainfall_mm` float DEFAULT NULL,
  PRIMARY KEY (`record_date`,`location_id`),
  KEY `location_id` (`location_id`),
  CONSTRAINT `climate_ibfk_1` FOREIGN KEY (`location_id`) REFERENCES `location` (`location_id`),
  CONSTRAINT `check_min_max_temperature` CHECK ((`temperature_min_celsius` <= `temperature_max_celsius`)),
  CONSTRAINT `check_rainfall_mm` CHECK ((`rainfall_mm` >= 0)),
  CONSTRAINT `check_temperature_max` CHECK (((`temperature_max_celsius` >= -(100)) and (`temperature_max_celsius` <= 60))),
  CONSTRAINT `check_temperature_min` CHECK (((`temperature_min_celsius` >= -(100)) and (`temperature_min_celsius` <= 60)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

