DROP TABLE IF EXISTS `disease_outbreaks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `disease_outbreaks` (
  `outbreak_id` int NOT NULL AUTO_INCREMENT,
  `disease_id` int NOT NULL,
  `animal_id` int NOT NULL,
  `location_id` int NOT NULL,
  `outbreak_year` year DEFAULT NULL,
  `disease_mortality_percent` decimal(4,2) DEFAULT NULL,
  PRIMARY KEY (`outbreak_id`),
  KEY `disease_id` (`disease_id`),
  KEY `animal_id` (`animal_id`),
  KEY `location_id` (`location_id`),
  CONSTRAINT `disease_outbreaks_ibfk_1` FOREIGN KEY (`disease_id`) REFERENCES `diseases` (`disease_id`),
  CONSTRAINT `disease_outbreaks_ibfk_2` FOREIGN KEY (`animal_id`) REFERENCES `animal` (`animal_id`),
  CONSTRAINT `disease_outbreaks_ibfk_3` FOREIGN KEY (`location_id`) REFERENCES `location` (`location_id`),
  CONSTRAINT `check_disease_mortality_percent` CHECK (((`disease_mortality_percent` >= 0) and (`disease_mortality_percent` <= 100))),
  CONSTRAINT `check_outbreak_year` CHECK ((`outbreak_year` >= 1750))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

